@namespace sv_bd6bec1aab3647e68cdc15cdb2991181.Components.Pages.Board

<div class="task-card">
    <div class="task-card-header">
        <span class="task-title">@Task.Title</span>
        <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    </div>
    <div class="task-card-body">
        <span class="task-assignee">@Task.Assignee</span>
        <span class="task-due-date">@Task.DueDate.ToString("MMM dd")</span>
    </div>
    <div class="task-card-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move btn-move-left" @onclick="OnMoveLeftClick">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move btn-move-right" @onclick="OnMoveRightClick">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public TaskItem Task { get; set; } = default!;

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback OnMoveRight { get; set; }

    private async System.Threading.Tasks.Task OnMoveLeftClick() => await OnMoveLeft.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRightClick() => await OnMoveRight.InvokeAsync();
}

@namespace sv_bd6bec1aab3647e68cdc15cdb2991181.Components.Pages.Board

@if (IsVisible)
{
    <div class="add-task-form">
        <div class="form-group">
            <label>Title</label>
            <input type="text" @bind="title" placeholder="Task title" />
        </div>
        <div class="form-group">
            <label>Assignee</label>
            <input type="text" @bind="assignee" placeholder="Assignee name" />
        </div>
        <div class="form-group">
            <label>Priority</label>
            <select @bind="priority">
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
            </select>
        </div>
        <div class="form-group">
            <label>Due Date</label>
            <input type="date" @bind="dueDate" />
        </div>
        <div class="form-actions">
            <button class="btn-save" @onclick="Save">Save</button>
            <button class="btn-cancel" @onclick="Cancel">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter]
    public bool IsVisible { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today;

    private async System.Threading.Tasks.Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnSave.InvokeAsync((title, assignee, priority, dueDate));
            ResetForm();
        }
    }

    private async System.Threading.Tasks.Task Cancel()
    {
        ResetForm();
        await OnCancel.InvokeAsync();
    }

    private void ResetForm()
    {
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today;
    }
}

@namespace sv_bd6bec1aab3647e68cdc15cdb2991181.Components.Pages.Board

<div class="kanban-column">
    <div class="kanban-column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>
    <div class="kanban-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => HandleMoveLeft(task)"
                      OnMoveRight="() => HandleMoveRight(task)" />
        }
    </div>
    <div class="kanban-column-footer">
        @if (!showAddForm)
        {
            <button class="btn-add-task" @onclick="() => showAddForm = true">+ Add Task</button>
        }
        <AddTaskForm IsVisible="showAddForm"
                     OnSave="HandleSave"
                     OnCancel="() => showAddForm = false" />
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool CanMoveLeft { get; set; }

    [Parameter]
    public bool CanMoveRight { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveLeft { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnMoveRight { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showAddForm;

    private async System.Threading.Tasks.Task HandleMoveLeft(TaskItem task) => await OnMoveLeft.InvokeAsync(task);
    private async System.Threading.Tasks.Task HandleMoveRight(TaskItem task) => await OnMoveRight.InvokeAsync(task);

    private async System.Threading.Tasks.Task HandleSave((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnAddTask.InvokeAsync(formData);
        showAddForm = false;
    }
}

@namespace sv_bd6bec1aab3647e68cdc15cdb2991181.Components.Pages.Board

<div class="board-search-bar">
    <input type="text" placeholder="Search tasks by title..." 
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async System.Threading.Tasks.Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}

@page "/board"
@namespace sv_bd6bec1aab3647e68cdc15cdb2991181.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<div class="kanban-board">
    @if (isLoading)
    {
        <div class="board-loading">Loading tasks...</div>
    }
    else if (errorMessage is not null)
    {
        <div class="board-error">
            <p>@errorMessage</p>
            <button @onclick="LoadTasks">Retry</button>
        </div>
    }
    else
    {
        <BoardStatsBar Tasks="allTasks" />
        <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

        <div class="kanban-columns">
            <KanbanColumn ColumnName="To Do"
                          Tasks="GetFilteredTasks("To Do")"
                          CanMoveLeft="false"
                          CanMoveRight="true"
                          OnMoveRight="task => MoveTask(task, "In Progress")"
                          OnAddTask="data => AddTask(data, "To Do")" />

            <KanbanColumn ColumnName="In Progress"
                          Tasks="GetFilteredTasks("In Progress")"
                          CanMoveLeft="true"
                          CanMoveRight="true"
                          OnMoveLeft="task => MoveTask(task, "To Do")"
                          OnMoveRight="task => MoveTask(task, "Done")"
                          OnAddTask="data => AddTask(data, "In Progress")" />

            <KanbanColumn ColumnName="Done"
                          Tasks="GetFilteredTasks("Done")"
                          CanMoveLeft="true"
                          CanMoveRight="false"
                          OnMoveLeft="task => MoveTask(task, "In Progress")"
                          OnAddTask="data => AddTask(data, "Done")" />
        </div>
    }
</div>

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async System.Threading.Tasks.Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async System.Threading.Tasks.Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async System.Threading.Tasks.Task MoveTask(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async System.Threading.Tasks.Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to add task: {ex.Message}";
        }
    }
}

